const { sessionId, chatInput } = $input.first().json.body ?? {};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const message = typeof chatInput === 'string' ? chatInput.trim() : '';
if (typeof sessionId !== 'string' || !uuid.test(sessionId) || !message || [...message].length > 2000) {
  return [{ json: { status: 400, body: { output: 'Envía una sesión válida y un mensaje de 1 a 2000 caracteres.', error: { code: 'INVALID_INPUT' } } } }];
}
return [{ json: { sessionKey: 'jaleco:' + sessionId.toLowerCase(), chatInput: message } }];

const { sessionId, draftId, confirmed } = $input.first().json.body ?? {};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (typeof sessionId !== 'string' || typeof draftId !== 'string' || !uuid.test(sessionId) || !uuid.test(draftId)) {
  return [{ json: { status: 400, body: { output: 'Envía una sesión y un borrador válidos.', error: { code: 'INVALID_INPUT' } } } }];
}
if (confirmed !== true) {
  return [{ json: { status: 400, body: { output: 'La radicación requiere confirmación explícita.', error: { code: 'CONFIRMATION_REQUIRED' } } } }];
}
return [{ json: { status: 503, body: { output: 'La radicación aún no está conectada en esta base.', error: { code: 'PERSISTENCE_UNAVAILABLE' } } } }];

const { chatInput } = $('Validar chat').first().json;
const history = $input.first().json.messages;
const extract = text => [...new Set((text.match(/\bJS-[0-9]{3}\b/gi) ?? []).map(id => id.toUpperCase()))];

const current = extract(chatInput);
if (current.length === 1) return [{ json: { chatInput, orderId: current[0], origin: 'current' } }];
if (current.length > 1) return [{ json: { chatInput, orderId: null, origin: 'ambiguous' } }];

const recent = history.filter(turn => typeof turn.human === 'string').slice(-6).reverse();
for (const turn of recent) {
  const previous = extract(turn.human);
  if (previous.length === 1) return [{ json: { chatInput, orderId: previous[0], origin: 'history' } }];
  if (previous.length > 1) return [{ json: { chatInput, orderId: null, origin: 'ambiguous' } }];
}
return [{ json: { chatInput, orderId: null, origin: 'missing' } }];

const agent = $input.first().json;
const { orderId, origin } = $('Resolver contexto del pedido').first().json;

function parseJson(value) {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return null; }
}

function fail(code, output) {
  return [{ json: { status: 503, body: { output, error: { code } } } }];
}

const agentError = "El agente de postventa no está disponible en este momento. Inténtalo de nuevo.";
const dataError = "No se pudo consultar la fuente de pedidos. Inténtalo de nuevo en unos minutos.";
if (agent.error != null) return fail('AGENT_UNAVAILABLE', agentError);

const labels = new Map([
  ['cambio_talla', 'cambio por talla'], ['defecto', 'producto defectuoso'],
  ['pedido_incompleto', 'pedido incompleto'], ['retracto', 'retracto'],
]);
const parsed = parseJson(agent.output);
const category = parsed && Object.keys(parsed).length === 1 && labels.has(parsed.category)
  ? parsed.category : 'sin_clasificar';

function reply(output, evidence = []) {
  return [{ json: { status: 200, body: { output, evidence, draft: null, classification: { category } } } }];
}

if (origin === 'ambiguous') return reply('Encontré varios números de pedido. ¿Cuál quieres consultar?');
const steps = Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : [];
const lookup = orderId && steps.findLast(step => step?.action?.tool === 'consultar_pedido');
if (!lookup) {
  if (origin === 'current') return fail('AGENT_UNAVAILABLE', agentError);
  return reply('¿Cuál es el número de tu pedido? Por ejemplo, JS-101.');
}

const observation = parseJson(lookup.observation);
const result = Array.isArray(observation) && observation.length === 1 ? observation[0] : observation;
if (!result || result.orderId !== orderId) return fail('DATA_SOURCE_UNAVAILABLE', dataError);
if (result.status === 'not_found') return reply('No encontré ese pedido. Verifica el número e inténtalo de nuevo.');
const row = result.data;
if (result.status !== 'found' || row?.orderId !== orderId ||
    !['sku', 'productName', 'channel', 'deliveredOn'].every(key => typeof row[key] === 'string' && row[key]) ||
    !Number.isInteger(row.warrantyMonths) || typeof row.requiresSerial !== 'boolean') {
  return fail('DATA_SOURCE_UNAVAILABLE', dataError);
}

const { sku, productName, channel, deliveredOn, warrantyMonths, requiresSerial } = row;
const data = { orderId, sku, productName, channel, deliveredOn, warrantyMonths, requiresSerial };
const evidence = [{ source: 'pedidos', recordId: orderId, data }];
const outcome = labels.has(category) ? ` Identifiqué el motivo como ${labels.get(category)}.` : '';
return reply(`El pedido ${orderId} corresponde a ${productName} y se entregó el ${deliveredOn}.${outcome}`, evidence);
